'use client';

import { useState, useTransition } from 'react';
import { useRouter } from 'next/navigation';
import { Modal } from '@/components/ui/modal';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import { formatMoney, formatDate } from '@/lib/utils';

type InvoiceStatus = 'DRAFT' | 'PENDING' | 'PAID' | 'OVERDUE' | 'CANCELLED';

interface Invoice {
  id: string;
  invoiceNumber: string;
  periodStart: string;
  periodEnd: string;
  status: InvoiceStatus;
  total: number;
  lineItemsCount: number;
  paidAt: string | null;
  createdAt: string;
}

interface LineItem {
  id: string;
  type: string;
  agentName: string | null;
  description: string;
  quantity: number;
  unitPrice: number;
  total: number;
}

const statusVariant: Record<InvoiceStatus, 'neutral' | 'warning' | 'success' | 'danger'> = {
  DRAFT: 'neutral',
  PENDING: 'warning',
  PAID: 'success',
  OVERDUE: 'danger',
  CANCELLED: 'neutral',
};

export function AdminBillingUserClient({
  userId,
  invoices: initialInvoices,
}: {
  userId: string;
  invoices: Invoice[];
}) {
  const router = useRouter();
  const [, startTransition] = useTransition();

  // View invoice modal
  const [viewInvoice, setViewInvoice] = useState<Invoice | null>(null);
  const [lineItems, setLineItems] = useState<LineItem[]>([]);
  const [loadingId, setLoadingId] = useState<string | null>(null);

  // Confirm action modal
  const [confirmModal, setConfirmModal] = useState<{
    invoiceId: string;
    action: 'PAID' | 'OVERDUE' | 'CANCELLED';
    label: string;
  } | null>(null);
  const [isActing, setIsActing] = useState(false);

  const formatPeriod = (start: string, end: string) => {
    const s = new Date(start);
    const e = new Date(end);
    return `${s.toLocaleDateString('en-US', { month: 'short', year: 'numeric' })} – ${e.toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' })}`;
  };

  const openInvoice = async (inv: Invoice) => {
    setLoadingId(inv.id);
    try {
      const res = await fetch(`/api/admin/billing/users/${userId}/invoices/${inv.id}`);
      if (res.ok) {
        const data = await res.json();
        setLineItems(data.lineItems);
        setViewInvoice(inv);
      }
    } finally {
      setLoadingId(null);
    }
  };

  const performAction = async () => {
    if (!confirmModal) return;
    setIsActing(true);
    await fetch(`/api/admin/billing/users/${userId}/invoices/${confirmModal.invoiceId}`, {
      method: 'PUT',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ status: confirmModal.action }),
    });
    setIsActing(false);
    setConfirmModal(null);
    startTransition(() => router.refresh());
  };

  return (
    <>
      {initialInvoices.length === 0 ? (
        <div className="bg-white rounded-xl border border-gray-200 p-12 text-center text-gray-400">
          No invoices yet.
        </div>
      ) : (
        <div className="bg-white rounded-xl border border-gray-200 overflow-hidden">
          <table className="w-full text-sm">
            <thead>
              <tr className="border-b border-gray-100 bg-gray-50">
                <th className="text-left px-4 py-3 text-xs font-medium text-gray-500 uppercase tracking-wide">Invoice #</th>
                <th className="text-left px-4 py-3 text-xs font-medium text-gray-500 uppercase tracking-wide">Period</th>
                <th className="text-right px-4 py-3 text-xs font-medium text-gray-500 uppercase tracking-wide">Total</th>
                <th className="text-left px-4 py-3 text-xs font-medium text-gray-500 uppercase tracking-wide">Status</th>
                <th className="text-left px-4 py-3 text-xs font-medium text-gray-500 uppercase tracking-wide">Date</th>
                <th className="text-right px-4 py-3 text-xs font-medium text-gray-500 uppercase tracking-wide">Actions</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-100">
              {initialInvoices.map(inv => (
                <tr key={inv.id} className="hover:bg-gray-50">
                  <td className="px-4 py-3 font-medium text-gray-900">{inv.invoiceNumber}</td>
                  <td className="px-4 py-3 text-gray-500 text-xs">{formatPeriod(inv.periodStart, inv.periodEnd)}</td>
                  <td className="px-4 py-3 text-right font-medium">{formatMoney(inv.total)}</td>
                  <td className="px-4 py-3">
                    <Badge variant={statusVariant[inv.status]}>{inv.status}</Badge>
                  </td>
                  <td className="px-4 py-3 text-gray-500">{formatDate(inv.createdAt)}</td>
                  <td className="px-4 py-3">
                    <div className="flex items-center justify-end gap-1">
                      <button
                        onClick={() => openInvoice(inv)}
                        disabled={loadingId === inv.id}
                        className="text-xs text-[#004D3E] hover:underline disabled:opacity-50 px-2"
                      >
                        View
                      </button>
                      {inv.status === 'PENDING' || inv.status === 'OVERDUE' ? (
                        <Button
                          size="sm"
                          variant="secondary"
                          onClick={() => setConfirmModal({ invoiceId: inv.id, action: 'PAID', label: 'Mark as Paid' })}
                        >
                          Mark Paid
                        </Button>
                      ) : null}
                      {inv.status === 'PENDING' ? (
                        <Button
                          size="sm"
                          variant="outline"
                          onClick={() => setConfirmModal({ invoiceId: inv.id, action: 'OVERDUE', label: 'Mark as Overdue' })}
                        >
                          Overdue
                        </Button>
                      ) : null}
                      {inv.status !== 'CANCELLED' && inv.status !== 'PAID' ? (
                        <Button
                          size="sm"
                          variant="ghost"
                          onClick={() => setConfirmModal({ invoiceId: inv.id, action: 'CANCELLED', label: 'Cancel Invoice' })}
                        >
                          Cancel
                        </Button>
                      ) : null}
                    </div>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}

      {/* View Invoice Modal */}
      <Modal
        isOpen={!!viewInvoice}
        onClose={() => setViewInvoice(null)}
        title={viewInvoice?.invoiceNumber ?? ''}
        size="lg"
      >
        {viewInvoice && (
          <div className="space-y-4">
            <div className="flex items-center justify-between text-sm">
              <span className="text-gray-500">Status</span>
              <Badge variant={statusVariant[viewInvoice.status]}>{viewInvoice.status}</Badge>
            </div>
            <div className="flex items-center justify-between text-sm">
              <span className="text-gray-500">Period</span>
              <span className="text-gray-900">{formatPeriod(viewInvoice.periodStart, viewInvoice.periodEnd)}</span>
            </div>
            <div className="border-t border-gray-100 pt-3">
              <p className="text-xs font-medium text-gray-500 uppercase tracking-wide mb-2">Line Items</p>
              <table className="w-full text-sm">
                <thead>
                  <tr className="text-xs text-gray-400">
                    <th className="text-left pb-2">Description</th>
                    <th className="text-right pb-2">Qty</th>
                    <th className="text-right pb-2">Unit Price</th>
                    <th className="text-right pb-2">Total</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-gray-50">
                  {lineItems.map(li => (
                    <tr key={li.id}>
                      <td className="py-2 text-gray-700">{li.description}</td>
                      <td className="py-2 text-right text-gray-500">{li.quantity}</td>
                      <td className="py-2 text-right text-gray-500">{formatMoney(li.unitPrice)}</td>
                      <td className="py-2 text-right font-medium">{formatMoney(li.total)}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
            <div className="border-t border-gray-100 pt-3 flex justify-end">
              <div className="text-right">
                <p className="text-sm text-gray-500">Total</p>
                <p className="text-xl font-bold text-gray-900">{formatMoney(viewInvoice.total)}</p>
              </div>
            </div>
          </div>
        )}
      </Modal>

      {/* Confirm Action Modal */}
      <Modal
        isOpen={!!confirmModal}
        onClose={() => setConfirmModal(null)}
        title={confirmModal?.label ?? ''}
        size="sm"
      >
        <div className="space-y-4">
          <p className="text-sm text-gray-600">
            Are you sure you want to {confirmModal?.label.toLowerCase()} this invoice?
          </p>
          <div className="flex justify-end gap-2">
            <Button variant="outline" onClick={() => setConfirmModal(null)}>Cancel</Button>
            <Button onClick={performAction} isLoading={isActing}>Confirm</Button>
          </div>
        </div>
      </Modal>
    </>
  );
}
